@push('scripts')<script>document.addEventListener('DOMContentLoaded',function(){const select=document.getElementById('transfer-method'),cards=[...document.querySelectorAll('[data-account-type]')];if(!cards.some(x=>x.dataset.accountType===select.value))select.value=cards[0].dataset.accountType;function update(){let count=0;cards.forEach(function(card){const visible=card.dataset.accountType===select.value;card.hidden=!visible;card.style.display=visible?'block':'none';const radio=card.querySelector('input');radio.disabled=!visible;if(!visible)radio.checked=false;if(visible)count++;});document.getElementById('no-transfer-account').hidden=count>0;document.getElementById('submit-transfer').disabled=count===0;}select.addEventListener('change',update);update();});</script>@endpush
